/**
 * Approval payload types for Trigger.dev Waitpoint-based engineer sign-off.
 *
 * Rationale: Separating types from task logic keeps f1_tasks.ts focused on
 * orchestration and allows approval payloads to be reused across tasks without
 * coupling. This mirrors the data contract between the pipeline and the Discord
 * approval button URL.
 */

/** Status returned when a Waitpoint is resumed via the approval webhook. */
export type ApprovalStatus = 'approved' | 'rejected' | 'auto_approved';

/**
 * Payload embedded in the Discord briefing preview message.
 * The resume URL is generated by Trigger.dev and expires after WAITPOINT_TIMEOUT_MINUTES.
 */
export interface BriefingPreview {
  /** F1 event name (e.g. "Monaco Grand Prix") */
  eventName: string;
  /** Round number within the season */
  round: number;
  /** Season year */
  year: number;
  /** Pipeline execution mode: Friday forecast or Monday audit */
  mode: 'forecast' | 'audit';
  /** One-sentence weather risk summary from WeatherIntelligence */
  weatherSummary: string;
  /** Trigger.dev signed URL to resume this run (approve the briefing) */
  approveUrl: string;
  /** ISO timestamp when the waitpoint auto-approves if no action is taken */
  autoApproveAt: string;
}

/**
 * Payload sent back when the Waitpoint is resumed (i.e. engineer taps Approve).
 * The status field allows the pipeline to distinguish human vs. timeout approval.
 */
export interface ApprovalPayload {
  status: ApprovalStatus;
  /** Engineer name or "auto" for timeout-based approval */
  approvedBy: string;
  /** Optional rejection reason (only present when status === 'rejected') */
  reason?: string;
}
